typedef struct {
  char method[16];
  char path[1024];
  char version[16];
} HttpRequest;

int parse_request_line(const char *buf, HttpRequest *req) {
  if (sscanf(buf, "%15s %1023s %15s", req->method, req->path, req->version) != 3) {
    return -1;
  }
  if (strcmp(req->method, "GET") != 0) {
    return 405;
  }
  if (req->path[0] != '/') {
    return -1;
  }
  return 0;
}
